import{_t as e,it as t,n,rt as r}from"./chunks/framework.Bb3LI7rT.js";var i=JSON.parse(`{"title":"Fieldset Spec 1.0","description":"","frontmatter":{},"headers":[],"relativePath":"spec/form-definition/1.0/index.md","filePath":"spec/form-definition/1.0/README.md"}`),a={name:`spec/form-definition/1.0/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<div><h1 id="fieldset-spec-10" tabindex="-1">Fieldset Spec 1.0 <a class="header-anchor" href="#fieldset-spec-10" aria-label="Permalink to “Fieldset Spec 1.0”">​</a></h1><p>Status: <strong>1.0.0</strong> · License: MIT · Meta-schema: <a href="meta-schema.json" target="_self"><code>meta-schema.json</code></a> (JSON Schema 2020-12) Meta-schema <code>$id</code>: <code>https://beyerenrico.github.io/fieldset/spec/form-definition/1.0/meta-schema.json</code> Meta-schema SHA-256: <code>fc73ec9a396356008df49fd872a5bd20408c8c8eb9ef09155bdc09c256b8eaeb</code> Role vocabulary: <a href="roles.json" target="_self"><code>roles.json</code></a> · Changes: <a href="/fieldset/spec/form-definition/1.0/changelog"><code>CHANGELOG.md</code></a> · Conformance: <a href="https://github.com/beyerenrico/fieldset/tree/v2.1.0-rc.4/spec/conformance" target="_blank" rel="noreferrer"><code>../../conformance/</code></a></p><p>The <code>$id</code> is an identifier. The docs site serves the meta-schema at that URL, but validators are advised to bundle a copy of <code>meta-schema.json</code>, checked against the SHA-256 above, rather than fetch it at runtime.</p><p>The key words MUST, MUST NOT, SHOULD and MAY are used as in RFC 2119. Two implementations (PHP <code>packages/fieldset-php</code>, TypeScript <code>packages/fieldset-js</code>) MUST produce identical results for every conformance case.</p><h2 id="1-concepts" tabindex="-1">1. Concepts <a class="header-anchor" href="#1-concepts" aria-label="Permalink to “1. Concepts”">​</a></h2><p>A <strong>Form Definition</strong> is one JSON document that describes structure, logic and presentation hints of a form. A <strong>submission</strong> is a JSON object with the data entered for a definition. Submission data is keyed by element <code>key</code>; repeaters produce arrays of row objects. Layout containers (<code>section</code>, <code>columns</code>) and pages do <strong>not</strong> create data nesting.</p><p>A <strong>scope</strong> is the root of the submission or one repeater row. Keys MUST be unique within a scope (including keys of elements inside sections, columns and pages of that scope). Element <code>id</code>s MUST be unique across the whole definition.</p><h2 id="2-definition" tabindex="-1">2. Definition <a class="header-anchor" href="#2-definition" aria-label="Permalink to “2. Definition”">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>$schema</code></td><td>string (URI)</td><td>no</td><td>URL of this meta-schema</td></tr><tr><td><code>specVersion</code></td><td>string</td><td>yes</td><td><code>1.0.0</code> (any <code>1.0.x</code> is accepted by 1.0 implementations)</td></tr><tr><td><code>key</code></td><td>key</td><td>yes</td><td>snake_case identifier of the form</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>locale</code></td><td>string</td><td>yes</td><td>BCP 47 tag, e.g. <code>de-DE</code>. Base language of all labels</td></tr><tr><td><code>settings</code></td><td>object</td><td>no</td><td>see below</td></tr><tr><td><code>pages</code></td><td>array</td><td>yes</td><td>at least one page</td></tr><tr><td><code>source</code></td><td>object</td><td>no</td><td>template lineage (§8)</td></tr><tr><td><code>x-*</code></td><td>any</td><td>no</td><td>extensions (§9)</td></tr></tbody></table><p><code>settings</code>:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>layout</code></td><td><code>wizard</code> | <code>scroll</code></td><td><code>scroll</code></td><td>one page at a time, or one long page</td></tr><tr><td><code>numbering</code></td><td>object</td><td>none</td><td><code>{ &quot;format&quot;: &quot;SR-{YYYY}-{SEQ:5}&quot;, &quot;reset&quot;: &quot;never&quot; | &quot;yearly&quot; | &quot;monthly&quot; }</code> (§7.3)</td></tr><tr><td><code>document.design</code></td><td>string</td><td><code>default</code></td><td>key of the document design used for renditions</td></tr><tr><td><code>sendToCustomer</code></td><td>boolean</td><td><code>false</code></td><td>the Field App may email the document to a recipient</td></tr></tbody></table><p>A <strong>key</strong> matches <code>^[a-z][a-z0-9_]{0,63}$</code>. An <strong>id</strong> is a UUID string (any version, lowercase or uppercase hex).</p><p>Page: <code>{ &quot;id&quot;?, &quot;key&quot;, &quot;title&quot;, &quot;description&quot;?, &quot;visibleIf&quot;?, &quot;elements&quot;: [...] }</code>. Page keys are unique among pages; they are not data keys.</p><h2 id="3-elements" tabindex="-1">3. Elements <a class="header-anchor" href="#3-elements" aria-label="Permalink to “3. Elements”">​</a></h2><h3 id="31-common-properties" tabindex="-1">3.1 Common properties <a class="header-anchor" href="#31-common-properties" aria-label="Permalink to “3.1 Common properties”">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>id</td><td>required; builder identity, stable across versions</td></tr><tr><td><code>type</code></td><td>string</td><td>required; §3.2</td></tr><tr><td><code>key</code></td><td>key</td><td>required; immutable once published (§6)</td></tr><tr><td><code>label</code></td><td>string</td><td>required for data elements; optional for layout</td></tr><tr><td><code>help</code>, <code>placeholder</code></td><td>string</td><td></td></tr><tr><td><code>required</code></td><td>boolean</td><td>default <code>false</code>; applies only while visible</td></tr><tr><td><code>visibleIf</code>, <code>requiredIf</code>, <code>readOnlyIf</code></td><td>logic</td><td>JsonLogic expression or boolean (§4)</td></tr><tr><td><code>default</code></td><td>logic</td><td>JsonLogic expression; literals are valid JsonLogic (§5.2)</td></tr><tr><td><code>validation</code></td><td>object</td><td>type-specific constraints (§3.3)</td></tr><tr><td><code>pdf</code></td><td>object</td><td><code>hidden</code> (bool), <code>label</code> (string), <code>width</code> (<code>full</code>|<code>half</code>|<code>third</code>), <code>keepTogether</code> (bool)</td></tr><tr><td><code>role</code></td><td>string</td><td>semantic role from <code>roles.json</code> (§8)</td></tr><tr><td><code>i18n</code></td><td>object</td><td>label maps (§8)</td></tr><tr><td><code>x-*</code></td><td>any</td><td>extensions (§9)</td></tr></tbody></table><p><code>readOnlyIf</code> is a presentation hint in 1.0: renderers disable the input; validators do not enforce it.</p><h3 id="32-types-and-data" tabindex="-1">3.2 Types and data <a class="header-anchor" href="#32-types-and-data" aria-label="Permalink to “3.2 Types and data”">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Extra properties</th><th>Data value</th></tr></thead><tbody><tr><td><code>text</code></td><td></td><td>string</td></tr><tr><td><code>textarea</code></td><td><code>rows</code> (int 2–20)</td><td>string</td></tr><tr><td><code>email</code></td><td></td><td>string, a valid email address</td></tr><tr><td><code>phone</code></td><td></td><td>string matching <code>^\\+?[0-9 ()./-]{3,32}$</code></td></tr><tr><td><code>number</code></td><td></td><td><strong>decimal string</strong> (§5.1)</td></tr><tr><td><code>money</code></td><td><code>currency</code> (ISO 4217, required), <code>scale</code> (int 0–4, default 2)</td><td>decimal string, normalized to exactly <code>scale</code> fraction digits</td></tr><tr><td><code>date</code></td><td></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>time</code></td><td></td><td><code>HH:MM</code> or <code>HH:MM:SS</code> (24 h)</td></tr><tr><td><code>datetime</code></td><td></td><td>RFC 3339 date-time with offset, e.g. <code>2026-10-16T09:41:00+02:00</code></td></tr><tr><td><code>select</code>, <code>radio</code></td><td><code>options</code> (required)</td><td>string: one option <code>value</code></td></tr><tr><td><code>multiselect</code></td><td><code>options</code> (required)</td><td>array of distinct option values</td></tr><tr><td><code>checkbox</code></td><td></td><td>boolean</td></tr><tr><td><code>toggle</code></td><td></td><td>boolean</td></tr><tr><td><code>rating</code></td><td><code>max</code> (int 3–10, default 5)</td><td>integer 1…<code>max</code></td></tr><tr><td><code>photo</code>, <code>file</code></td><td><code>multiple</code> (bool, default false)</td><td>attachment id (UUID string); array of ids when <code>multiple</code></td></tr><tr><td><code>signature</code></td><td><code>signerNameFrom</code> (key)</td><td><code>{ &quot;attachment&quot;: id, &quot;signerName&quot;: string, &quot;signedAt&quot;: date-time }</code></td></tr><tr><td><code>location</code></td><td></td><td><code>{ &quot;lat&quot;: number, &quot;lng&quot;: number, &quot;accuracy&quot;: number ≥ 0, &quot;capturedAt&quot;: date-time }</code></td></tr><tr><td><code>calculated</code></td><td><code>expression</code> (required), <code>format</code> (<code>number</code>|<code>money</code>|<code>text</code>, default <code>number</code>), <code>scale</code> (int 0–10), <code>currency</code></td><td>computed (§5.4); client input is ignored</td></tr><tr><td><code>hidden</code></td><td></td><td>string, integer or boolean; not shown to the user</td></tr><tr><td><code>repeater</code></td><td><code>elements</code> (required), <code>display</code> (<code>cards</code>|<code>table</code>, default <code>cards</code>), <code>minItems</code>, <code>maxItems</code>, <code>addLabel</code>, <code>itemLabel</code></td><td>array of row objects</td></tr><tr><td><code>section</code></td><td><code>elements</code> (required), <code>collapsible</code> (bool)</td><td>none (layout)</td></tr><tr><td><code>columns</code></td><td><code>columns</code> (required): 2–4 items <code>{ &quot;elements&quot;: [...] }</code></td><td>none (layout)</td></tr><tr><td><code>heading</code></td><td><code>text</code> (required), <code>level</code> (1–3, default 2)</td><td>none</td></tr><tr><td><code>paragraph</code></td><td><code>text</code> (required; Markdown, rendered sanitized, no raw HTML)</td><td>none</td></tr><tr><td><code>divider</code></td><td></td><td>none</td></tr><tr><td><code>image</code></td><td><code>src</code> (required: <code>data:image/png|jpeg|webp;base64,…</code> or <code>asset:&lt;uuid&gt;</code>), <code>alt</code></td><td>none</td></tr><tr><td><code>page_break</code></td><td></td><td>none; forces a page break in PDFs only</td></tr></tbody></table><p>Options: <code>{ &quot;value&quot;: string (1–100 chars), &quot;label&quot;: string, &quot;i18n&quot;?: { &quot;label&quot;: {…} } }</code>. Option values MUST be unique within one element.</p><p>Reserved type names that 1.0 rejects: <code>record</code> (snapshot semantics reserved, §8), <code>barcode</code>, <code>rich_text</code>, <code>lookup</code>.</p><p>Layout elements (<code>section</code>, <code>columns</code>, <code>heading</code>, <code>paragraph</code>, <code>divider</code>, <code>image</code>, <code>page_break</code>) carry an <code>id</code> and a <code>key</code> but never data.</p><h3 id="33-validation-constraints" tabindex="-1">3.3 Validation constraints <a class="header-anchor" href="#33-validation-constraints" aria-label="Permalink to “3.3 Validation constraints”">​</a></h3><table tabindex="0"><thead><tr><th>Constraint</th><th>Applies to</th><th>Meaning</th></tr></thead><tbody><tr><td><code>minLength</code>, <code>maxLength</code></td><td>text, textarea, email, phone</td><td>length in Unicode code points</td></tr><tr><td><code>pattern</code></td><td>text, textarea, phone</td><td>regular expression in the restricted ECMAScript syntax of §3.4, implicitly unanchored</td></tr><tr><td><code>min</code>, <code>max</code></td><td>number, money</td><td>inclusive bounds (JSON numbers or decimal strings)</td></tr><tr><td><code>min</code>, <code>max</code></td><td>date, datetime, time</td><td>inclusive bounds as value strings of the same type</td></tr><tr><td><code>min</code>, <code>max</code></td><td>multiselect</td><td>number of selected options</td></tr><tr><td><code>step</code></td><td>number, money</td><td>value − (<code>min</code> or 0) MUST be an exact multiple of <code>step</code></td></tr><tr><td><code>accept</code></td><td>photo, file</td><td>array of MIME types or <code>type/*</code> wildcards</td></tr><tr><td><code>maxFiles</code></td><td>photo, file (multiple)</td><td>maximum number of attachments</td></tr><tr><td><code>maxSizeKb</code></td><td>photo, file, signature</td><td>enforced by the server on upload, not by the validator</td></tr></tbody></table><p>Numeric constraint values in a definition MAY be JSON numbers with at most 15 significant digits.</p><p>Checks of one element run in this order and stop at the first failure: type/format → <code>scale</code> → <code>min_length</code> → <code>max_length</code> → <code>pattern</code>, and <code>min</code> → <code>max</code> → <code>step</code> (numbers, money, dates, counts).</p><h3 id="34-pattern-syntax-and-semantics" tabindex="-1">3.4 Pattern syntax and semantics <a class="header-anchor" href="#34-pattern-syntax-and-semantics" aria-label="Permalink to “3.4 Pattern syntax and semantics”">​</a></h3><p><code>pattern</code> uses a <strong>restricted subset of ECMAScript regular expressions</strong> so every implementation matches identically and no pattern can trigger catastrophic backtracking. Anything outside the subset is a lint error (<code>invalid_pattern</code>); evaluators treat an invalid pattern as &quot;no constraint&quot;.</p><ul><li><strong>Atoms:</strong> literal characters except the syntax characters <code>^ $ \\ . * + ? ( ) [ ] { } |</code>; <code>.</code>; character classes <code>[…]</code> / <code>[^…]</code> with literals, ranges <code>a-z</code> and the class escapes below (an unescaped <code>[</code> inside a class is invalid); escapes <code>\\d \\D \\w \\W \\s \\S</code>, <code>\\t \\n \\r \\f \\v</code>, <code>\\0</code> (not followed by a digit), <code>\\xHH</code>, <code>\\uHHHH</code>, <code>\\u{H…}</code> (≤ 10FFFF), and an escaped syntax character or <code>/</code> or <code>-</code>. <code>\\b</code> / <code>\\B</code> are assertions outside classes and invalid inside them.</li><li><strong>Structure:</strong> <code>^</code>, <code>$</code>, groups <code>(…)</code>, <code>(?:…)</code>, lookaheads <code>(?=…)</code>, <code>(?!…)</code>, alternation <code>|</code>.</li><li><strong>Quantifiers:</strong> <code>*</code>, <code>+</code>, <code>?</code>, <code>{n}</code>, <code>{n,}</code>, <code>{n,m}</code> with <code>n ≤ m ≤ 1000</code>, each optionally followed by <code>?</code> (lazy).</li><li><strong>Not allowed:</strong> backreferences, named groups, lookbehind, inline flags, Unicode property escapes, and any other syntax; a quantifier other than <code>?</code>/<code>{0,1}</code> applied to a group that contains a quantifier or an alternation (e.g. <code>(a+)+</code>, <code>(a|b)*</code>, <code>(\\d{3}-){2}</code>).</li><li><strong>Semantics:</strong> ECMAScript with the <code>u</code> flag, case-sensitive, no multiline/dotAll: matching works on code points; <code>.</code> matches any code point except <code>\\n \\r \\u2028 \\u2029</code>; <code>^</code>/<code>$</code> match only at the start and end of the value; <code>\\d</code> = <code>[0-9]</code>, <code>\\w</code> = <code>[A-Za-z0-9_]</code>, <code>\\b</code> uses that <code>\\w</code>; <code>\\s</code> = the ECMAScript WhiteSpace and LineTerminator set (<code>\\t \\n \\v \\f \\r</code>, space, U+00A0, U+1680, U+2000–U+200A, U+2028, U+2029, U+202F, U+205F, U+3000, U+FEFF — not U+0085 or U+180E).</li><li><strong>Size:</strong> a value longer than 4,096 code points fails the <code>pattern</code> check; if an engine hits an internal matching limit the check fails as well (fail closed).</li></ul><h2 id="4-logic-jsonlogic-dialect" tabindex="-1">4. Logic (JsonLogic dialect) <a class="header-anchor" href="#4-logic-jsonlogic-dialect" aria-label="Permalink to “4. Logic (JsonLogic dialect)”">​</a></h2><p>All logic properties take a <strong>JsonLogic</strong> expression (jsonlogic.com) or a boolean. Implementations MUST implement the dialect below exactly; they MUST NOT rely on host-language comparison or truthiness.</p><h3 id="41-truthiness-and-equality" tabindex="-1">4.1 Truthiness and equality <a class="header-anchor" href="#41-truthiness-and-equality" aria-label="Permalink to “4.1 Truthiness and equality”">​</a></h3><ul><li>Falsy: <code>false</code>, <code>null</code>, <code>0</code>, <code>&quot;&quot;</code>, <code>[]</code>. Everything else is truthy (including <code>&quot;0&quot;</code> and <code>{}</code>).</li><li><code>==</code> / <code>!=</code> use JavaScript abstract equality restricted to JSON values: <code>null == null</code>; a number and a string compare as numbers (<code>Number(string)</code> rules: whitespace trimmed, empty string = 0, <code>0x</code>/exponent forms accepted, unparsable = NaN); a boolean converts to 1/0 first; arrays (also array vs array) compare by converting to their comma-joined string; objects are never equal.</li><li><code>===</code> / <code>!==</code> compare type and value; arrays and objects are never strictly equal.</li><li><code>&lt;</code>, <code>&lt;=</code>, <code>&gt;</code>, <code>&gt;=</code>: if both operands are strings, compare by Unicode code points; otherwise convert both to numbers (<code>null</code> → 0, booleans → 1/0, numeric strings → number, other → NaN; any NaN → false). <code>&lt;</code> and <code>&lt;=</code> accept three operands (between).</li></ul><h3 id="42-supported-operators" tabindex="-1">4.2 Supported operators <a class="header-anchor" href="#42-supported-operators" aria-label="Permalink to “4.2 Supported operators”">​</a></h3><p><code>var</code>, <code>missing</code>, <code>missing_some</code>, <code>if</code> (alias <code>?:</code>), <code>==</code>, <code>===</code>, <code>!=</code>, <code>!==</code>, <code>!</code>, <code>!!</code>, <code>or</code>, <code>and</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>in</code>, <code>cat</code>, <code>substr</code>, <code>merge</code>, <code>map</code>, <code>filter</code>, <code>reduce</code>, <code>all</code>, <code>none</code>, <code>some</code>, <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>%</code>, plus the custom operators of §5.3. <code>min</code> and <code>max</code> are replaced by the decimal versions of §5.3. Any other operator is a lint error (<code>unknown_operator</code>).</p><p><code>or</code>/<code>and</code> return the deciding operand (not a boolean) and short-circuit. <code>if</code> evaluates only the chosen branch. <code>!</code>/<code>!!</code> apply truthiness to their first argument (or the argument itself if not an array). <code>in</code> tests substring (string haystack) or membership (array haystack, strict equality). <code>cat</code> joins the string forms (<code>null</code> → <code>&quot;&quot;</code>, numbers in shortest round-trip form, booleans <code>true</code>/<code>false</code>); <code>in</code> converts a non-string needle with JavaScript <code>String()</code>; <code>substr</code> counts code points. <code>+ - * / %</code> operate on IEEE-754 doubles (NaN or infinite results become <code>null</code>) and MUST NOT be used on number or money values (lint error). Unknown operators and nesting deeper than 512 levels (counting nested objects and arrays; a scalar is 0, <code>{&quot;!&quot;: true}</code> is 1) are evaluation errors; evaluators treat the whole expression as <code>null</code>. Definitions and submission data nested deeper than 1,024 levels (objects and arrays) are rejected when they are decoded.</p><h3 id="43-variables-and-scope" tabindex="-1">4.3 Variables and scope <a class="header-anchor" href="#43-variables-and-scope" aria-label="Permalink to “4.3 Variables and scope”">​</a></h3><p><code>{&quot;var&quot;: &quot;a.b&quot;}</code> reads a dotted path; <code>{&quot;var&quot;: [&quot;a&quot;, fallback]}</code> returns <code>fallback</code> when the value is <code>null</code>/missing; <code>{&quot;var&quot;: &quot;&quot;}</code> returns the whole scope object. Numeric path segments index arrays.</p><p>Evaluation scope for an element:</p><ol><li>Built-ins: <code>$today</code> (<code>YYYY-MM-DD</code>), <code>$now</code> (RFC 3339), <code>$user</code> <code>{name, email}</code>, <code>$org</code> <code>{name}</code>, <code>$form</code> <code>{version}</code> — supplied by the host as evaluation context (in the organization&#39;s time zone).</li><li><code>$root</code>: the root data object.</li><li>The root scope: every key defined at root level (value or <code>null</code>).</li><li>Inside a repeater row: every key defined in that row, shadowing outer keys with the same name; nested repeaters shadow again. <code>$row</code> is the current row object.</li></ol><p>Resolution is by <strong>definition</strong>, not by data presence: a key defined in the row resolves to the row&#39;s value even when that value is <code>null</code>. Inside <code>map</code>/<code>filter</code>/<code>reduce</code>/<code>all</code>/<code>none</code>/<code>some</code>, <code>var</code> resolves against the current item (<code>reduce</code>: <code>current</code>, <code>accumulator</code>) exactly as in JsonLogic.</p><p>Values of invisible elements (§5.5) resolve to <code>null</code>.</p><h2 id="5-values-calculations-and-validation" tabindex="-1">5. Values, calculations and validation <a class="header-anchor" href="#5-values-calculations-and-validation" aria-label="Permalink to “5. Values, calculations and validation”">​</a></h2><h3 id="51-decimal-strings" tabindex="-1">5.1 Decimal strings <a class="header-anchor" href="#51-decimal-strings" aria-label="Permalink to “5.1 Decimal strings”">​</a></h3><p><code>number</code> and <code>money</code> values are <strong>decimal strings</strong> matching <code>^-?(0|[1-9][0-9]*)(\\.[0-9]+)?$</code> with at most <strong>60 digits</strong> in total (integer plus fraction digits). Longer strings are <code>invalid_number</code>. JSON numbers are rejected for these types (<code>decimal_string_required</code>). Canonical output form: no exponent, no <code>+</code>, <code>-0</code> normalized to <code>0</code> (keeping scale, e.g. <code>0.00</code>).</p><h3 id="52-defaults" tabindex="-1">5.2 Defaults <a class="header-anchor" href="#52-defaults" aria-label="Permalink to “5.2 Defaults”">​</a></h3><p>When a visible element&#39;s value is missing or <code>null</code>, its <code>default</code> expression is evaluated in the element&#39;s scope and the result (if not <code>null</code>) becomes the value before validation. Defaults are not applied to <code>calculated</code> elements.</p><h3 id="53-custom-operators" tabindex="-1">5.3 Custom operators <a class="header-anchor" href="#53-custom-operators" aria-label="Permalink to “5.3 Custom operators”">​</a></h3><p>Operands of decimal operators are decimal strings of at most 60 digits, JSON integers (a JSON number whose IEEE-754 double value is integral, such as <code>2</code> or <code>2.0</code>, with magnitude ≤ 2^53), or <code>null</code>. Anything else (JSON numbers with a fractional part, invalid strings, booleans, arrays, objects) counts as <code>null</code>. Aggregates (<code>sum</code>, <code>min</code>, <code>max</code>, <code>count</code>) treat a non-array first operand as an empty array (for <code>min</code>/<code>max</code> see the table).</p><table tabindex="0"><thead><tr><th>Operator</th><th>Result</th></tr></thead><tbody><tr><td><code>dec.add</code> / <code>dec.sub</code> <code>[a, b, …]</code></td><td>exact; result scale = largest input scale; <code>null</code> if any operand is <code>null</code></td></tr><tr><td><code>dec.mul</code> <code>[a, b, …]</code></td><td>exact; result scale = sum of input scales; <code>null</code> if any operand is <code>null</code></td></tr><tr><td><code>dec.div</code> <code>[a, b, scale]</code></td><td>rounded half-up (away from zero) to <code>scale</code> (required JSON integer 0–20, else <code>null</code>); <code>null</code> if <code>b</code> is 0 or an operand is <code>null</code></td></tr><tr><td><code>dec.round</code> <code>[a, scale]</code></td><td>rounded half-up to <code>scale</code> (JSON integer 0–20, else <code>null</code>)</td></tr><tr><td><code>dec.eq</code>, <code>dec.gt</code>, <code>dec.gte</code>, <code>dec.lt</code>, <code>dec.lte</code> <code>[a, b]</code></td><td>numeric comparison; <code>false</code> if either is <code>null</code></td></tr><tr><td><code>sum</code> <code>[array, rowKey?]</code></td><td>decimal sum of <code>array[i][rowKey]</code> (or of the items when <code>rowKey</code> is omitted), skipping <code>null</code>; <code>&quot;0&quot;</code> for an empty array; scale = largest item scale</td></tr><tr><td><code>min</code> / <code>max</code> <code>[array, rowKey?]</code> or <code>[a, b, …]</code></td><td>aggregate form when the first operand is an array or the only operand, otherwise variadic over all operands; smallest/largest decimal, skipping <code>null</code>; <code>null</code> if none; the result keeps the winning item&#39;s own scale, ties keep the first</td></tr><tr><td><code>count</code> <code>[array]</code></td><td>number of non-<code>null</code> items as an integer</td></tr><tr><td><code>date.diff</code> <code>[from, to, unit]</code></td><td>integer <code>to − from</code>, truncated toward zero. Dates: <code>days</code>, <code>weeks</code>, <code>months</code>, <code>years</code>. Date-times: <code>minutes</code>, <code>hours</code>, <code>days</code> (24 h). Mixed or invalid input → <code>null</code></td></tr><tr><td><code>date.add</code> <code>[value, amount, unit]</code></td><td>date (or date-time keeping its offset) plus integer <code>amount</code> (JSON integer or integer string); months/years clamp the day to the month&#39;s end. Units as for <code>date.diff</code>. Date-times are output as <code>YYYY-MM-DDTHH:MM:SS</code> plus the input&#39;s offset (<code>Z</code> stays <code>Z</code>), without fractional seconds</td></tr></tbody></table><p><code>date.diff</code> on date-times includes fractional seconds before truncating. Month difference between dates <code>a ≤ b</code>: <code>(yb − ya) × 12 + (mb − ma)</code>, minus 1 when <code>db &lt; da</code>; <code>date.diff(b, a) = −date.diff(a, b)</code>; <code>years = trunc(months / 12)</code>; <code>weeks = trunc(days / 7)</code>.</p><h3 id="54-calculated-elements" tabindex="-1">5.4 Calculated elements <a class="header-anchor" href="#54-calculated-elements" aria-label="Permalink to “5.4 Calculated elements”">​</a></h3><p>A <code>calculated</code> element&#39;s value is its <code>expression</code> evaluated in its scope, then:</p><ul><li><code>format: number</code> / <code>money</code>: converted to a decimal (non-decimal results become <code>null</code>), rounded half-up to <code>scale</code> (default 2 for money, 6 for number) and stored with <strong>exactly</strong> <code>scale</code> fraction digits.</li><li><code>format: text</code>: <code>null</code> stays <code>null</code>, strings stay, other values become their <code>cat</code> string form.</li></ul><p>Client-supplied values for calculated elements are discarded. Calculations run in dependency order (row-level calculations before aggregates that reference their repeater). A definition whose calculated elements depend on each other cyclically is invalid (lint <code>cycle</code>).</p><h3 id="55-evaluation-algorithm" tabindex="-1">5.5 Evaluation algorithm <a class="header-anchor" href="#55-evaluation-algorithm" aria-label="Permalink to “5.5 Evaluation algorithm”">​</a></h3><p>Given a definition, input data and context, a conforming evaluator:</p><ol><li><strong>Normalizes</strong> the input: drops keys not defined in the scope (recursively in rows; layout keys are never data keys); a repeater value that is not an array becomes <code>[]</code> and reports <code>type_mismatch</code>; non-object rows are dropped with <code>type_mismatch</code> at the row pointer (later rows shift down; a <code>null</code> repeater counts as empty). Normalization errors are reported even if the repeater ends up invisible and in addition to validation errors; money values that pass the type check are rewritten with exactly <code>scale</code> fraction digits. Logic sees a <strong>view</strong> of the data in which values failing their element&#39;s type check (§5.6, codes up to <code>invalid_location</code> in the table) are <code>null</code>; the data itself keeps them for error reporting.</li><li>Sets every <code>calculated</code> value to <code>null</code>, then repeats up to 5 rounds until visibility <strong>and</strong> the data (calculated values and applied defaults) stop changing: a. compute visibility top-down in document order: a page, container or element is visible when its own <code>visibleIf</code> is truthy (missing = visible) and its parent is visible; inside repeaters per row. Each decision is visible to later elements of the same pass (an element found invisible reads as <code>null</code>); b. apply defaults (§5.2) to visible elements; c. compute calculated values in dependency order, treating invisible values as <code>null</code>. The order is a topological sort of the <strong>static</strong> dependencies (a <code>var</code> — including <code>$root.x</code> — whose first path segment resolves through the scope chain to another calculated element, or to a repeater, which depends on every calculated element inside its rows; references inside per-item arguments of iteration operators, computed paths and whole-scope references do not count); among elements that are ready, the earliest in document order goes first. Each value sees the values computed before it in the same round. Missing <code>today</code>/<code>now</code> context values resolve to <code>null</code>.</li><li><strong>Strips</strong> invisible elements&#39; values from the data (keys removed; invisible repeaters removed with their rows).</li><li><strong>Validates</strong> every visible data element (§5.6) in document order, rows in index order.</li></ol><p>Output:</p><ul><li><code>data</code>: the normalized, stripped data. A key is present when the input supplied it, a default filled it, or it is a visible <code>calculated</code> element (always present, possibly <code>null</code>).</li><li><code>errors</code>: compared by conformance runners as a set of <code>(pointer, code)</code> pairs.</li><li><code>visibility</code>: a map from the scope pointer of every element (layout elements included, e.g. <code>/details</code> or <code>/items/0/note</code>) to a boolean.</li></ul><p>The <code>hidden</code> type keeps a client-supplied string, integer or boolean; otherwise its <code>default</code> applies.</p><h3 id="56-validation-rules-and-error-codes" tabindex="-1">5.6 Validation rules and error codes <a class="header-anchor" href="#56-validation-rules-and-error-codes" aria-label="Permalink to “5.6 Validation rules and error codes”">​</a></h3><p>Errors are objects <code>{ &quot;pointer&quot;: &quot;/items/2/qty&quot;, &quot;code&quot;: &quot;...&quot;, &quot;params&quot;?: {...} }</code>. Pointers are JSON Pointers (RFC 6901) into the submission data. Codes are stable and localized by clients.</p><p>An element is <strong>required</strong> when <code>required</code> is true or <code>requiredIf</code> is truthy. A value is <strong>empty</strong> when it is missing, <code>null</code>, <code>&quot;&quot;</code>, or <code>[]</code>. Empty values are valid unless required — except that a repeater&#39;s <code>minItems</code> also applies to an empty or missing list (<code>min_items</code>). Type checks run before constraints; the first failing check of an element is reported (one validation error per element per value). <code>rating</code> has no type check: any non-integer or out-of-range value is <code>out_of_range</code>. Attachment shape errors are always <code>invalid_attachment</code>. A non-object signature or location is <code>type_mismatch</code>; objects must have exactly the documented members, otherwise <code>invalid_signature</code> / <code>invalid_location</code>. A <code>hidden</code> value that is not a string, integer or boolean is replaced by its default when one applies, otherwise <code>type_mismatch</code>. Email values longer than 254 code points are <code>invalid_email</code>; shorter ones are matched against the email pattern with the §3.4 semantics. Location numbers must be finite. Type checks run before the required check for non-empty values (a required checkbox holding <code>&quot;true&quot;</code> is <code>type_mismatch</code>).</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>required</code></td><td>required and empty; for <code>checkbox</code>: required and not <code>true</code>; for <code>repeater</code>: required with no rows</td></tr><tr><td><code>type_mismatch</code></td><td>wrong JSON type (e.g. number for text, string for checkbox, object for select)</td></tr><tr><td><code>decimal_string_required</code></td><td>JSON number given for number/money</td></tr><tr><td><code>invalid_number</code></td><td>string that is not a decimal string</td></tr><tr><td><code>scale_exceeded</code></td><td>money value with more fraction digits than <code>scale</code> (params <code>scale</code>)</td></tr><tr><td><code>invalid_email</code>, <code>invalid_phone</code>, <code>invalid_date</code>, <code>invalid_time</code>, <code>invalid_datetime</code></td><td>malformed value. Email: <code>^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$</code>. Date: a real calendar date. Time: <code>HH:MM</code> or <code>HH:MM:SS</code>, hours 00–23. Date-time: <code>YYYY-MM-DDTHH:MM:SS(.fraction)?(Z|±HH:MM)</code> with a real date and time</td></tr><tr><td><code>invalid_option</code></td><td>value (or any multiselect item) not among the options; duplicates in multiselect</td></tr><tr><td><code>invalid_attachment</code></td><td>attachment id not a UUID; non-array for <code>multiple</code>, array for single</td></tr><tr><td><code>invalid_signature</code>, <code>invalid_location</code></td><td>malformed object</td></tr><tr><td><code>min_length</code> / <code>max_length</code></td><td>params <code>limit</code></td></tr><tr><td><code>pattern</code></td><td>value does not match <code>pattern</code></td></tr><tr><td><code>min</code> / <code>max</code></td><td>numeric, date/time or count bound violated; params <code>limit</code></td></tr><tr><td><code>step</code></td><td>not a multiple of <code>step</code>; params <code>step</code></td></tr><tr><td><code>min_items</code> / <code>max_items</code></td><td>repeater row count or <code>maxFiles</code>; params <code>limit</code></td></tr><tr><td><code>out_of_range</code></td><td>rating outside 1…<code>max</code> or non-integer</td></tr></tbody></table><h2 id="6-versioning-rules" tabindex="-1">6. Versioning rules <a class="header-anchor" href="#6-versioning-rules" aria-label="Permalink to “6. Versioning rules”">​</a></h2><ul><li>Keys are immutable once an element <code>id</code> appears in a published version (<code>key_locked</code>).</li><li>A key that exists in a published version MUST keep its type (<code>key_type_changed</code>).</li><li>A published version is immutable. Rollback creates a new version with copied content.</li><li>The <strong>checksum</strong> of a definition is the lowercase hex SHA-256 of its canonical JSON: object keys sorted by code point, no insignificant whitespace, <code>/</code> not escaped, non-ASCII characters unescaped (UTF-8), numbers in shortest round-trip form.</li></ul><h2 id="7-linting" tabindex="-1">7. Linting <a class="header-anchor" href="#7-linting" aria-label="Permalink to “7. Linting”">​</a></h2><p>Lint results: <code>{ &quot;severity&quot;: &quot;error&quot; | &quot;warning&quot;, &quot;code&quot;, &quot;path&quot;, &quot;params&quot;? }</code>, where <code>path</code> is a JSON Pointer into the <strong>definition</strong>. A definition with lint errors MUST NOT be published.</p><table tabindex="0"><thead><tr><th>Code</th><th>Severity</th><th>Rule</th></tr></thead><tbody><tr><td><code>duplicate_key</code></td><td>error</td><td>key not unique in its scope</td></tr><tr><td><code>duplicate_page_key</code></td><td>error</td><td>page key not unique</td></tr><tr><td><code>duplicate_id</code></td><td>error</td><td>element id not unique in the definition</td></tr><tr><td><code>duplicate_option_value</code></td><td>error</td><td>option value repeated in an element</td></tr><tr><td><code>unknown_reference</code></td><td>error</td><td><code>var</code> path, <code>signerNameFrom</code>, or <code>sum</code>/<code>min</code>/<code>max</code> row key that resolves to no defined key or built-in</td></tr><tr><td><code>unknown_operator</code></td><td>error</td><td>operator outside §4.2 / §5.3</td></tr><tr><td><code>decimal_builtin_operator</code></td><td>error</td><td><code>+ - * / % &lt; &lt;= &gt; &gt;= == != === !==</code> with an operand that is a <code>var</code> of a number, money or numeric calculated element</td></tr><tr><td><code>float_literal</code></td><td>error</td><td>non-integer JSON number literal as an operand of a decimal operator (§5.3)</td></tr><tr><td><code>cycle</code></td><td>error</td><td>cyclic dependency between calculated elements</td></tr><tr><td><code>invalid_numbering_format</code></td><td>error</td><td>numbering format invalid (§7.3)</td></tr><tr><td><code>invalid_repeater_bounds</code></td><td>error</td><td><code>minItems</code> &gt; <code>maxItems</code></td></tr><tr><td><code>invalid_pattern</code></td><td>error</td><td><code>pattern</code> is outside the §3.4 subset</td></tr><tr><td><code>logic_too_deep</code></td><td>error</td><td>a logic expression nests deeper than 512 levels</td></tr><tr><td><code>reserved_type</code></td><td>error</td><td>element type reserved for later versions (e.g. <code>record</code>)</td></tr><tr><td><code>key_locked</code></td><td>error</td><td>element id published earlier with a different key</td></tr><tr><td><code>key_type_changed</code></td><td>error</td><td>key published earlier with a different type</td></tr><tr><td><code>unknown_role</code></td><td>warning</td><td><code>role</code> not in <code>roles.json</code></td></tr><tr><td><code>duplicate_role</code></td><td>error</td><td>same <code>role</code> twice in one scope (repeater rows are their own scope)</td></tr><tr><td><code>empty_page</code></td><td>warning</td><td>page without elements</td></tr></tbody></table><p><code>path</code> points at the offending property (for logic: the logic property itself, e.g. <code>/pages/0/elements/3/visibleIf</code>; <code>reserved_type</code> at <code>/type</code>; <code>duplicate_id</code> at the element). References must resolve to <strong>data</strong> keys (layout keys are not data); built-in objects check their member (<code>$user.name|email</code>, <code>$org.name</code>, <code>$form.version</code>). Whole-scope references (<code>&quot;&quot;</code>, <code>$root</code>, <code>$row</code>) add no calculation dependencies. References inside the per-item argument of <code>map</code>, <code>filter</code>, <code>reduce</code>, <code>all</code>, <code>none</code> and <code>some</code> are not reference-checked. A cycle is reported once, at the first calculated element of the cycle in document order (pre-order traversal of pages and elements). Duplicates are reported at the second and later occurrences.</p><p><code>key_locked</code> and <code>key_type_changed</code> need the published history; linters accept it as an optional list of earlier definitions.</p><h3 id="73-numbering-format" tabindex="-1">7.3 Numbering format <a class="header-anchor" href="#73-numbering-format" aria-label="Permalink to “7.3 Numbering format”">​</a></h3><p>Tokens: <code>{YYYY}</code>, <code>{YY}</code>, <code>{MM}</code>, <code>{SEQ:n}</code> (n = 1–12, zero-padded width). <code>{SEQ:n}</code> MUST appear exactly once; literal text is <code>[A-Za-z0-9._/-]</code>. <code>reset: yearly</code> requires <code>{YYYY}</code> or <code>{YY}</code>; <code>reset: monthly</code> requires a year token and <code>{MM}</code>.</p><h2 id="8-reserved-for-later-features-no-behavior-in-10-beyond-storage-and-validation" tabindex="-1">8. Reserved for later features (no behavior in 1.0 beyond storage and validation) <a class="header-anchor" href="#8-reserved-for-later-features-no-behavior-in-10-beyond-storage-and-validation" aria-label="Permalink to “8. Reserved for later features (no behavior in 1.0 beyond storage and validation)”">​</a></h2><ul><li><strong><code>role</code></strong> (D11): string from <code>roles.json</code>. Webhook payloads and exports include each value&#39;s role.</li><li><strong><code>source</code></strong> (D12): <code>{ &quot;registry&quot;: URI, &quot;template&quot;: key, &quot;version&quot;: semver }</code>; set on template import, kept on clone.</li><li><strong><code>i18n</code></strong> (D13): <code>{ &quot;label&quot;?: {lang: string}, &quot;help&quot;?: {...}, &quot;placeholder&quot;?: {...} }</code> on elements and <code>{ &quot;label&quot;?: {...} }</code> on options. 1.0 renderers use only the base <code>locale</code>.</li><li><strong><code>record</code></strong> (D10): when it ships, selecting a record <strong>copies</strong> its values into the submission (snapshot), never a live reference. 1.0 rejects the type.</li></ul><h2 id="9-extensions" tabindex="-1">9. Extensions <a class="header-anchor" href="#9-extensions" aria-label="Permalink to “9. Extensions”">​</a></h2><p>Properties starting with <code>x-</code> are allowed on the definition, pages, elements and options and MUST be preserved by tools that round-trip definitions. Documented extensions:</p><ul><li><code>x-import</code> (element): <code>{ &quot;source&quot;: &quot;acroform&quot;, &quot;field&quot;: string, &quot;page&quot;: int, &quot;rect&quot;: [x1, y1, x2, y2], &quot;confidence&quot;: 0–1 }</code> — provenance of elements created by the fillable-PDF importer.</li></ul><h2 id="10-data-contract-export" tabindex="-1">10. Data contract export <a class="header-anchor" href="#10-data-contract-export" aria-label="Permalink to “10. Data contract export”">​</a></h2><p>Implementations SHOULD export a JSON Schema 2020-12 describing the <strong>data</strong> of a definition (types and structure only; not a validator): root object with one property per data element; repeaters as arrays of objects; number/money as strings with the decimal pattern; <code>date</code>/<code>date-time</code> as <code>format</code>, <code>time</code> as a pattern (JSON Schema&#39;s <code>time</code> format requires an offset). The schema describes non-empty values.</p></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};